-- -----------------------------------------------------
-- INPUT DEVICES (Fallback Kit)
-- -----------------------------------------------------

hl.gesture({
    fingers = 3,
    direction = "horizontal",
    action = "workspace",
})

-- Keyboard Layout (Dynamically generated by installer from profile.conf)
local ok, _ = pcall(require, "modules.keyboard")
if not ok then
    hl.config({
        input = {
            kb_layout = "us",
            kb_variant = "",
            kb_options = "",
        },
    })
end

hl.config({
    input = {
        repeat_rate = 50,
        repeat_delay = 300,
        numlock_by_default = true,
        follow_mouse = 1,
        sensitivity = 0,
        touchpad = {
            natural_scroll = true,
        },
    },
    misc = {
        mouse_move_enables_dpms = true,
        key_press_enables_dpms = true,
    },
})

